CREATE COLUMN TABLE "TEST_AP"."OBOD" ("BIOD_ENTRY" INTEGER CS_INT NOT NULL , "BIOD_UID" SMALLINT CS_INT, "BIOD_QID" INTEGER CS_INT, "BIOD_QN" NVARCHAR(100), "BIOD_QLD" LONGDATE CS_LONGDATE, "BIOD_QLT" SMALLINT CS_INT, PRIMARY KEY ("BIOD_ENTRY")) UNLOAD PRIORITY 5  AUTO MERGE ;
CREATE INDEX "OBOD_USERID" ON "TEST_AP"."OBOD" ( "BIOD_UID" ASC )